-- ------------------------------------------------------------
--  마스터 FK 연결
-- ------------------------------------------------------------
update legacy_settlements l set retailer_id = r.id
  from retailers r where r.code = l.retailer_code and l.retailer_id is null;
update legacy_settlements l set workshop_id = w.id
  from workshops w where w.code = l.workshop_code and l.workshop_id is null;

-- ------------------------------------------------------------
--  실제 정산유형 코드로 맞춘다 (030 으로 만들었으면 이미 일치해서 0행)
-- ------------------------------------------------------------
update legacy_settlements l set type_code = t.code
  from settlement_types t
 where l.item = 'ASAP_SUPPORT' and l.type_code <> t.code
   and (t.name ilike '%전시차%' or t.code = 'ASAP_SUPPORT');
update legacy_settlements l set type_code = t.code
  from settlement_types t
 where l.item in ('ASAP_SVC','ASAP_SALES') and l.type_code <> t.code
   and (t.name ilike '%ASAP%Incentive%' or t.code = 'ASAP_INCENTIVE');

-- ------------------------------------------------------------
--  검증
-- ------------------------------------------------------------
select period_key, period_label,
       sum(case when item='ASAP_SUPPORT' then amount end) as 전시차지원,
       sum(case when item='ASAP_SVC'     then amount end) as 인센티브_Service,
       sum(case when item='ASAP_SALES'   then amount end) as 인센티브_Sales,
       count(*) as rows
from legacy_settlements
where type_code in ('ASAP_SUPPORT','ASAP_INCENTIVE')
   or item in ('ASAP_SUPPORT','ASAP_SVC','ASAP_SALES')
group by period_key, period_label
order by period_key;

select l.type_code, t.name, count(*) as rows, sum(l.amount) as 누적
from legacy_settlements l
left join settlement_types t on t.code = l.type_code
where l.item in ('ASAP_SUPPORT','ASAP_SVC','ASAP_SALES')
group by l.type_code, t.name;
